INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Arbeiten hier alle isoliert?', 2, '[{"text": "Nein", "correct": true, "because": "Zusammenarbeit ist zentral"}, {"text": "Ja", "correct": false, "because": "Teamübergreifend gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip verkürzt manuelle Aufgaben?', 3, '[{"text": "Automatisierung", "correct": true, "because": "Prozesse effizienter machen"}, {"text": "Zusammenarbeit", "correct": false, "because": "Fokus auf Teamarbeit"}, {"text": "Kontinuierliche Verbesserung", "correct": false, "because": "Optimierung langfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundwerte fördern kürzere Release-Zyklen?', 5, '[{"text": "Zusammenarbeit", "correct": true, "because": "Teamübergreifende Kooperation"}, {"text": "Automatisierung", "correct": true, "because": "Schnellere Prozesse"}, {"text": "Manuelle Arbeit", "correct": false, "because": "Verlangsamt Zyklen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Automatisierung spart Zeit. b) Zusammenarbeit ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zusammenarbeit essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Prinzipien?', 4, '[{"text": "Zusammenarbeit", "correct": false, "because": "Teamarbeit zentral"}, {"text": "Kontinuierliche Verbesserung", "correct": false, "because": "Optimierung nötig"}, {"text": "Siloarbeit", "correct": true, "because": "Kooperation bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verbesserung hier einmalig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich gefördert"}, {"text": "Ja", "correct": false, "because": "Fortlaufender Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für Teamkoordination?', 3, '[{"text": "Zusammenarbeit", "correct": true, "because": "Teamübergreifend abstimmen"}, {"text": "Automatisierung", "correct": false, "because": "Technische Effizienz"}, {"text": "Kontinuierliche Verbesserung", "correct": false, "because": "Langfristige Optimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte unterstützen schnelle Releases?', 5, '[{"text": "Automatisierung", "correct": true, "because": "Prozesse beschleunigen"}, {"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Effizienz steigern"}, {"text": "Manuelle Prozesse", "correct": false, "because": "Verlangsamen Zyklen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Zusammenarbeit fördert Effizienz. b) Automatisierung ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisierung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Zusammenarbeit", "correct": false, "because": "Teamkooperation nötig"}, {"text": "Automatisierung", "correct": false, "because": "Effizienz steigern"}, {"text": "Manuelle Kontrolle", "correct": true, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Zusammenarbeit hier zweitrangig?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Teamarbeit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern Prozessoptimierung?', 4, '[{"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Prozesse anpassen"}, {"text": "Automatisierung", "correct": true, "because": "Effizienz erhöhen"}, {"text": "Statische Abläufe", "correct": false, "because": "Dynamik zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier alles manuell läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung ist Kern"}, {"text": "Ja", "correct": false, "because": "Prozesse automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für kürzere Zyklen?', 3, '[{"text": "Automatisierung", "correct": true, "because": "Schnelligkeit fördern"}, {"text": "Manuelle Tests", "correct": false, "because": "Verlangsamen Prozess"}, {"text": "Einzelarbeit", "correct": false, "because": "Zusammenarbeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verbesserung ist fortlaufend. b) Teams arbeiten getrennt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zusammenarbeit zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Prinzipien?', 5, '[{"text": "Schnelle Releases", "correct": true, "because": "Automatisierung hilft"}, {"text": "Bessere Teamarbeit", "correct": true, "because": "Zusammenarbeit fördert"}, {"text": "Langsame Prozesse", "correct": false, "because": "Effizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Kontinuierliche Verbesserung", "correct": false, "because": "Optimierung zentral"}, {"text": "Zusammenarbeit", "correct": false, "because": "Teamfokus"}, {"text": "Isolierte Teams", "correct": true, "because": "Kooperation bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Automatisierung hier optional?', 3, '[{"text": "Nein", "correct": true, "because": "Kernprinzip für Effizienz"}, {"text": "Ja", "correct": false, "because": "Automatisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verbesserung hier stagniert?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich angestrebt"}, {"text": "Ja", "correct": false, "because": "Fortlaufende Optimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für Teamübergreifung?', 4, '[{"text": "Zusammenarbeit", "correct": true, "because": "Kooperation fördern"}, {"text": "Manuelle Arbeit", "correct": false, "because": "Automatisierung zählt"}, {"text": "Statische Prozesse", "correct": false, "because": "Dynamik nötig"}]');
